void extractZipSafely(ZipInputStream zis, Path targetDir) throws IOException {
    ZipEntry entry;
    while ((entry = zis.getNextEntry()) != null) {
        Path entryPath = targetDir.resolve(entry.getName()).normalize();
        if (!entryPath.startsWith(targetDir)) {
            throw new SecurityException("Zip slip wykryty we wpisie: " + entry.getName());
        }
        Files.copy(zis, entryPath, StandardCopyOption.REPLACE_EXISTING); // bezpieczne
    }
}

